hpy-001.text:
I will parse each version string into its numeric components (major, minor, patch) and a list of pre‑release identifiers (ignoring build metadata). The numeric parts are compared first; if they match, the presence of a pre‑release makes the version lower, and the identifiers are compared left‑to‑right, treating numeric identifiers as integers and alphanumeric ones as strings, with the rule that a longer list wins when all preceding identifiers are equal.

```python
def cmp_semver(a, b):
    def parse(v):
        # Strip build metadata
        v = v.split('+', 1)[0]
        # Split into core and pre‑release
        parts = v.split('-', 1)
        core = parts[0]
        prerelease = parts[1].split('.') if len(parts) > 1 else []
        major, minor, patch = map(int, core.split('.'))
        return (major, minor, patch, prerelease)

    a_core = parse(a)
    b_core = parse(b)

    # Compare numeric parts
    for i in range(3):
        if a_core[i] < b_core[i]:
            return -1
        if a_core[i] > b_core[i]:
            return 1

    # Both have same numeric version
    a_pr = a_core[3]
    b_pr = b_core[3]

    # Pre‑release handling
    if not a_pr and not b_pr:
        return 0
    if not a_pr:
        return 1
    if not b_pr:
        return -1

    # Compare identifiers
    for i in range(min(len(a_pr), len(b_pr))):
        a_id = a_pr[i]
        b_id = b_pr[i]
        a_is_num = a_id.isdigit()
        b_is_num = b_id.isdigit()
        if a_is_num and b_is_num:
            a_val = int(a_id)
            b_val = int(b_id)
            if a_val < b_val:
                return -1
            if a_val > b_val:
                return 1
        else:
            # At least one is non‑numeric; compare as strings
            if a_id < b_id:
                return -1
            if a_id > b_id:
                return 1

    # All compared identifiers equal; longer list wins
    if len(a_pr) < len(b_pr):
        return -1
    if len(a_pr) > len(b_pr):
        return 1
    return 0
```

