hpy-012.text:
The solution parses each cron field into a list of allowed values, handling ranges, steps, and lists. It then iterates forward from the given `after` datetime, checking each candidate minute‑second combination against the parsed fields. The day‑of‑month and day‑of‑week rules are applied with an OR when both are restricted and an AND when only one is restricted. If any field is malformed, a `ValueError` is raised.

ANSWER:  
```python
import re
from datetime import datetime, timedelta

def _parse_field(field, min_val, max_val):
    if field == '*':
        return list(range(min_val, max_val + 1))
    values = set()
    for part in field.split(','):
        if '/' in part:
            base, step = part.split('/')
            step = int(step)
            if base == '*':
                start, end = min_val, max_val
            else:
                if '-' in base:
                    start, end = map(int, base.split('-'))
                else:
                    start = end = int(base)
            for v in range(start, end + 1, step):
                if min_val <= v <= max_val:
                    values.add(v)
        else:
            if '-' in part:
                start, end = map(int, part.split('-'))
                for v in range(start, end + 1):
                    if min_val <= v <= max_val:
                        values.add(v)
            else:
                v = int(part)
                if min_val <= v <= max_val:
                    values.add(v)
    if not values:
        raise ValueError(f"No valid values for field '{field}'")
    return sorted(values)

def next_fire(expr, after):
    parts = expr.strip().split()
    if len(parts) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")
    minute_vals = _parse_field(parts[0], 0, 59)
    hour_vals   = _parse_field(parts[1], 0, 23)
    day_vals    = _parse_field(parts[2], 1, 31)
    month_vals  = _parse_field(parts[3], 1, 12)
    dow_vals    = _parse_field(parts[4], 0, 6)

    cur = after + timedelta(seconds=1)
    cur = cur.replace(second=0, microsecond=0)

    while True:
        if cur.month not in month_vals:
            cur = (cur.replace(day=1, hour=0, minute=0) +
                   timedelta(days=32)).replace(day=1)
            continue
        if cur.day not in day_vals:
            cur = cur.replace(hour=0, minute=0)
            cur += timedelta(days=1)
            continue
        dow = cur.weekday()  # Monday=0 … Sunday=6
        if cur.day not in day_vals and dow not in dow_vals:
            cur = cur.replace(hour=0, minute=0)
            cur += timedelta(days=1)
            continue
        if cur.hour not in hour_vals:
            cur = cur.replace(minute=0)
            cur += timedelta(hours=1)
            continue
        if cur.minute not in minute_vals:
            cur = cur.replace(second=0, microsecond=0)
            cur += timedelta(minutes=1)
            continue
        return cur
```

