hpy-014.text:
I'll implement a recursive descent parser that handles the specified operators and precedence. The approach involves tokenizing the input string, then parsing expressions with different precedence levels using separate functions for each level. Unary operators are handled by checking for a minus or plus immediately after an opening parenthesis or at the start of an expression.

The key challenge is correctly handling the right-associativity of `**` and ensuring it binds tighter than unary minus. I'll also need to carefully manage parentheses and ensure that division is true division. Edge cases include empty expressions, mismatched parentheses, invalid characters, and expressions that end with an operator.

```python
def evaluate(expr):
    if not expr or not expr.strip():
        raise ValueError("Empty expression")

    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i] in '+-*/%()':
            tokens.append(expr[i])
            i += 1
        elif expr[i] == '.':
            # Handle decimal point
            if i + 1 < len(expr) and expr[i + 1].isdigit():
                # Find the full number
                j = i
                while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                    j += 1
                tokens.append(expr[i:j])
                i = j
            else:
                raise ValueError(f"Invalid character: {expr[i]}")
        elif expr[i].isdigit():
            # Handle integer or decimal
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            tokens.append(expr[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {expr[i]}")

    # Parser functions
    def parse_expression(pos):
        # Parse addition and subtraction
        left, pos = parse_term(pos)
        while pos < len(tokens) and tokens[pos] in '+-':
            op = tokens[pos]
            pos += 1
            right, pos = parse_term(pos)
            if op == '+':
                left += right
            else:
                left -= right
        return left, pos

    def parse_term(pos):
        # Parse multiplication, division, modulo
        left, pos = parse_power(pos)
        while pos < len(tokens) and tokens[pos] in '*/%':
            op = tokens[pos]
            pos += 1
            right, pos = parse_power(pos)
            if op == '*':
                left *= right
            elif op == '/':
                left /= right
            else:  # %
                left %= right
        return left, pos

    def parse_power(pos):
        # Parse exponentiation (right-associative)
        left, pos = parse_unary(pos)
        if pos < len(tokens) and tokens[pos] == '**':
            pos += 1
            right, pos = parse_power(pos)  # Right-associative
            left = left ** right
        return left, pos

    def parse_unary(pos):
        # Handle unary plus and minus
        if pos < len(tokens) and tokens[pos] in '+-':
            op = tokens[pos]
            pos += 1
            val, pos = parse_unary(pos)  # Recursive for multiple unary operators
            if op == '-':
                return -val, pos
            else:
                return val, pos
        else:
            return parse_primary(pos)

    def parse_primary(pos):
        # Handle numbers and parentheses
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")

        token = tokens[pos]
        if token == '(':
            pos += 1
            val, pos = parse_expression(pos)
            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError("Mismatched parentheses")
            pos += 1
            return val, pos
        elif token in '+-*/%()':
            raise ValueError(f"Unexpected operator: {token}")
        else:
            # Number
            try:
                if '.' in token:
                    val = float(token)
                else:
                    val = int(token)
                return val, pos + 1
            except ValueError:
                raise ValueError(f"Invalid number: {token}")

    # Start parsing
    result, pos = parse_expression(0)
    if pos != len(tokens):
        raise ValueError("Malformed expression")

    return result
```

