The `RollbackDSU` maintains a list of parent and size arrays, and a stack of changes (child, old_parent, root, old_size) to support undo. Each `union` records the modification before applying it, and `snapshot` simply returns the current stack length as an opaque token. Rolling back to a token pops changes from the stack until that length, restoring the previous state. Path compression is omitted to keep the structure reversible.

```python
class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.stack = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        # record state before change
        self.stack.append((rb, self.parent[rb], ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

    def snapshot(self):
        return len(self.stack)

    def rollback(self, token):
        while len(self.stack) > token:
            rb, old_parent, ra, old_size = self.stack.pop()
            self.parent[rb] = old_parent
            self.size[ra] = old_size

    def components(self):
        return sum(1 for i in range(len(self.parent)) if self.parent[i] == i)
```

