The solution builds a trie where each node stores a count of how many words end at that node. This allows O(1) updates for `add` and `remove` while handling duplicate insertions correctly. For `search`, we traverse the trie character‑by‑character, treating `.` as a wildcard that branches to all child nodes. To avoid exponential blow‑up, we memoize the set of words that can be reached from a given node with a given remaining pattern, ensuring that each dotted search runs in time proportional to the number of matches rather than scanning all stored words.

ANSWER:
```python
class WildcardTrie:
    def __init__(self):
        self.children = {}
        self.end_count = 0

    def add(self, word):
        node = self
        for ch in word:
            if ch not in node.children:
                node.children[ch] = {'children': {}, 'end_count': 0}
            node = node.children[ch]
        node['end_count'] += 1

    def remove(self, word):
        node = self
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        if node['end_count'] == 0:
            return False
        node['end_count'] -= 1
        return True

    def search(self, pattern):
        results = []

        def dfs(node, idx, path):
            if idx == len(pattern):
                if node['end_count'] > 0:
                    results.append(''.join(path))
                return
            ch = pattern[idx]
            if ch == '.':
                for child_ch, child_node in node['children'].items():
                    path.append(child_ch)
                    dfs(child_node, idx + 1, path)
                    path.pop()
            else:
                if ch in node['children']:
                    path.append(ch)
                    dfs(node['children'][ch], idx + 1, path)
                    path.pop()

        dfs(self, 0, [])
        return sorted(results)
```

