I'll implement a Spreadsheet class that handles cell values and formulas with dependency tracking. The approach uses a graph to track dependencies and caches computed values with lazy evaluation. When a cell is set, I'll detect cycles using DFS and invalidate dependent cells. For O(1) amortized get, I'll use a cache that's cleared when dependencies change.

```python
class Spreadsheet:
    def __init__(self):
        self.values = {}  # cell -> (value, is_formula)
        self.dependencies = {}  # cell -> set of dependent cells
        self.cache = {}  # cell -> computed value
        self.parsing_stack = set()  # for cycle detection

    def set(self, cell, value):
        # Check for cycles
        if isinstance(value, str) and value.startswith('='):
            if self._would_create_cycle(cell, value):
                raise ValueError("Reference cycle detected")

        # Save old value for rollback
        old_value = self.values.get(cell)

        # Set new value
        is_formula = isinstance(value, str) and value.startswith('=')
        self.values[cell] = (value, is_formula)

        # Clear cache for this cell and all dependents
        self._invalidate(cell)

        # If we had a cycle, rollback
        if isinstance(value, str) and value.startswith('='):
            if self._would_create_cycle(cell, value):
                self.values[cell] = old_value
                raise ValueError("Reference cycle detected")

    def get(self, cell):
        # Return cached value if available
        if cell in self.cache:
            return self.cache[cell]

        # Compute value
        if cell not in self.values:
            self.cache[cell] = 0
            return 0

        value, is_formula = self.values[cell]
        if not is_formula:
            self.cache[cell] = value
            return value

        # Evaluate formula
        result = self._evaluate_formula(value)
        self.cache[cell] = result
        return result

    def _would_create_cycle(self, cell, formula):
        self.parsing_stack.add(cell)
        try:
            # Extract cell references from formula
            refs = self._extract_cell_refs(formula)
            for ref in refs:
                if ref in self.parsing_stack:
                    return True
                # Check if setting this cell would create a cycle through dependencies
                if ref in self.values and self.values[ref][1]:  # if ref is a formula
                    if self._would_create_cycle(ref, self.values[ref][0]):
                        return True
            return False
        finally:
            self.parsing_stack.discard(cell)

    def _extract_cell_refs(self, formula):
        # Simple extraction of cell references (e.g., A1, B2)
        import re
        return re.findall(r'[A-Z]+\d+', formula)

    def _evaluate_formula(self, formula):
        # Replace cell references with their values
        import re
