I will implement a debounce function that supports leading and trailing options, along with cancel and flush methods. The function will handle edge cases such as immediate invocation when leading is true, proper argument and this binding for the trailing call, and correct behavior when both leading and trailing are enabled.

ANSWER: 
```javascript
function debounce(fn, wait, options = {}) {
  const { leading = false, trailing = true } = options;
  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;
  let lastResult = null;

  const invokeFunction = () => {
    if (timeoutId !== null) {
      timeoutId = null;
      lastResult = fn.apply(lastThis, lastArgs);
    }
  };

  const debounced = function (...args) {
    lastArgs = args;
    lastThis = this;

    const callNow = leading && timeoutId === null;

    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(invokeFunction, wait);

    if (callNow) {
      lastResult = fn.apply(this, args);
    }

    return lastResult;
  };

  debounced.cancel = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  debounced.flush = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
      invokeFunction();
    }
    return lastResult;
  };

  return debounced;
}

module.exports = debounce;
