I will implement the JSON Pointer functions by first handling the special empty pointer case, then decoding the tilde escapes, splitting the path, and iterating through the tokens while respecting array indexing and the `-` append rule. For `get`, I’ll return `undefined` when a token is missing and throw an error for an invalid pointer that doesn’t start with `/` and isn’t empty; for `set`, I’ll create intermediate objects as needed and return the modified document.

ANSWER:
```javascript
function decode(token) {
  return token.replace(/~1/g, '/').replace(/~0/g, '~');
}

function get(doc, pointer) {
  if (pointer === '') return doc;
  if (!pointer.startsWith('/')) throw new Error('Invalid pointer');
  const tokens = pointer.substring(1).split('/');
  let current = doc;
  for (const token of tokens) {
    const key = decode(token);
    if (current == null || !(key in current)) return undefined;
    current = current[key];
  }
  return current;
}

function set(doc, pointer, value) {
  if (pointer === '') return (doc = value);
  if (!pointer.startsWith('/')) throw new Error('Invalid pointer');
  const tokens = pointer.substring(1).split('/');
  let current = doc;
  for (let i = 0; i < tokens.length - 1; i++) {
    const token = tokens[i];
    const key = decode(token);
    if (current[key] == null) current[key] = {};
    current = current[key];
  }
  const lastToken = tokens[tokens.length - 1];
  const lastKey = decode(lastToken);
  if (lastKey === '-') {
    if (Array.isArray(current)) current.push(value);
    else current[lastKey] = value;
  } else {
    const num = Number(lastKey);
    if (!isNaN(num) && Number.isInteger(num)) {
      if (Array.isArray(current)) {
        if (num >= current.length) current.length = num + 1;
        current[num] = value;
      } else {
        current[lastKey] = value;
      }
    } else {
      current[lastKey] = value;
    }
  }
  return doc;
}

module.exports = { get, set };
```

