I will implement an `Emitter` class that maintains a map of event names to arrays of listener functions. The `on` method will push listeners onto the array and return an unsubscribe function that removes the listener by index. The `once` method will wrap the listener in a closure that removes itself after the first invocation. The `emit` method will iterate over a copy of the listener array, invoking each listener with the provided arguments while handling errors by collecting them and rethrowing the first one after the loop. Listeners added or removed during an emit will be respected by operating on the snapshot array, ensuring they are not invoked in the same emit cycle.

ANSWER:
```javascript
class Emitter {
  constructor() {
    this.events = new Map();
  }

  on(event, fn) {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    const listeners = this.events.get(event);
    listeners.push(fn);
    return () => {
      const index = listeners.indexOf(fn);
      if (index !== -1) listeners.splice(index, 1);
    };
  }

  once(event, fn) {
    const wrapped = (...args) => {
      const unsubscribe = this.on(event, () => {});
      unsubscribe();
      fn(...args);
    };
    return this.on(event, wrapped);
  }

  off(event, fn) {
    if (!this.events.has(event)) return;
    const listeners = this.events.get(event);
    const index = listeners.indexOf(fn);
    if (index !== -1) listeners.splice(index, 1);
  }

  emit(event, ...args) {
    if (!this.events.has(event)) return 0;
    const listeners = this.events.get(event);
    const snapshot = listeners.slice();
    let invoked = 0;
    const errors = [];
    for (const fn of snapshot) {
      try {
        fn(...args);
        invoked++;
      } catch (e) {
        errors.push(e);
      }
    }
    if (errors.length > 0) {
      throw errors[0];
    }
    return invoked;
  }
}

module.exports = Emitter;
```

