I will create a recursive `observe` function that returns a Proxy for any plain object or array. The Proxy will intercept property assignments and deletions, building a path array from the root to the changed property. When a value is written, it will compare the new value with the old one using SameValueZero semantics; if they differ, it will call `onChange` with the path, new value, and old value. For deletions, the reported old value will be the value that was removed, and the new value will be `undefined`. To handle nested objects that are added later, the Proxy will wrap any newly assigned plain object or array with another Proxy that also observes its own mutations. Array methods like `push` will be overridden to ensure each element insertion is reported individually with its index.

ANSWER:
```javascript
function observe(target, onChange, path = []) {
  const handler = {
    get(obj, prop, receiver) {
      const value = Reflect.get(obj, prop, receiver);
      if (typeof value === 'object' && value !== null) {
        return observe(value, onChange, [...path, prop]);
      }
      return value;
    },
    set(obj, prop, value, receiver) {
      const oldValue = obj[prop];
      if (Object.is(value, oldValue)) return true;
      obj[prop] = value;
      onChange([...path, prop], value, oldValue);
      return true;
    },
    deleteProperty(obj, prop) {
      const oldValue = obj[prop];
      delete obj[prop];
      onChange([...path, prop], undefined, oldValue);
      return true;
    }
  };

  const proxy = new Proxy(target, handler);

  if (Array.isArray(target)) {
    const arrayHandler = {
      get(arr, prop, receiver) {
        if (prop === 'push') {
          return function (...items) {
            const result = Reflect.apply(Array.prototype.push, arr, items);
            for (let i = arr.length - items.length; i < arr.length; i++) {
              onChange([...path, 'push', i], arr[i], undefined);
            }
            return result;
          };
        }
        return Reflect.get(arr, prop, receiver);
      }
    };
    return new Proxy(proxy, arrayHandler);
  }

  return proxy;
}

