hjs-013.text:
I will implement `parseQuery` by splitting the query string on '&' and then processing each key-value pair, handling percent‑decoding, converting `+` to spaces, and recursively building nested objects or arrays based on bracket notation. For `buildQuery`, I will traverse the object, generate keys with proper bracket syntax, percent‑encode values, sort keys alphabetically, and concatenate them into a query string while ignoring any leading '?'.

ANSWER:
```javascript
function parseQuery(qs) {
  if (!qs) return {};
  if (qs.startsWith('?')) qs = qs.substring(1);
  const result = {};
  const pairs = qs.split('&');
  for (const pair of pairs) {
    if (!pair) continue;
    let [key, value = ''] = pair.split('=');
    key = decodeURIComponent(key.replace(/\+/g, ' '));
    value = decodeURIComponent(value.replace(/\+/g, ' '));
    const match = key.match(/^(.*?)\[([^\]]*)\]$/);
    if (match) {
      const base = match[1];
      const sub = match[2];
      if (!result[base]) result[base] = {};
      if (sub === '') {
        if (!Array.isArray(result[base])) result[base] = [];
        result[base].push(value);
      } else {
        result[base][sub] = value;
      }
    } else {
      if (!result[key]) result[key] = value;
      else if (Array.isArray(result[key])) result[key].push(value);
      else result[key] = [result[key], value];
    }
  }
  return result;
}

function buildQuery(obj) {
  const parts = [];
  function recurse(prefix, val) {
    if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
      Object.keys(val).sort().forEach(k => {
        recurse(prefix ? `${prefix}[${k}]` : k, val[k]);
      });
    } else if (Array.isArray(val)) {
      val.forEach(v => {
        recurse(prefix ? `${prefix}[]` : prefix, v);
      });
    } else {
      const encodedKey = encodeURIComponent(prefix);
      const encodedVal = encodeURIComponent(val);
      parts.push(`${encodedKey}=${encodedVal}`);
    }
  }
  Object.keys(obj).sort().forEach(k => recurse(k, obj[k]));
  return parts.join('&');
}

module.exports = { parseQuery, buildQuery };
```

