hjs-014.text:
I will implement a Redux‑style store that captures the current state, maintains a list of subscribers, and processes each dispatch by first snapshotting the subscriber list, then notifying each subscriber with the new state. The reducer will be invoked for every action, and I will guard against dispatching from within the reducer by checking the call stack. Subscribers added or removed during a notification will not affect the current round, and dispatching from inside a subscriber will be allowed and fully processed before the outer dispatch continues.

ANSWER:
```javascript
function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];

  function getState() {
    return state;
  }

  function dispatch(action) {
    // Prevent dispatch from inside the reducer
    const stack = new Error().stack;
    if (stack.includes('dispatch')) {
      throw new Error('Dispatching while processing dispatch is not allowed');
    }

    state = reducer(state, action);

    // Snapshot the listeners list for this dispatch
    const snapshot = listeners.slice();
    for (const listener of snapshot) {
      listener();
    }

    return action;
  }

  function subscribe(fn) {
    listeners.push(fn);
    return function unsubscribe() {
      const index = listeners.indexOf(fn);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  // Initialize the store with an empty action
  dispatch({ type: '@@INIT' });

  return { getState, dispatch, subscribe };
}

module.exports = createStore;
```

