I will first explain my approach and edge cases, then provide the requested JavaScript code.

My approach involves performing a topological sort on the task dependencies to determine the execution order. I'll use a depth-first search algorithm to detect cycles and build the sorted order. For execution, I'll run tasks in batches where each batch contains tasks with no unresolved dependencies, allowing independent tasks to run concurrently within each batch. I'll handle edge cases such as missing dependencies by throwing an error with the appropriate message, and I'll ensure that if any task rejects, the overall promise rejects with that error while still allowing unrelated tasks to complete.

ANSWER:
```javascript
module.exports = async function toposortTasks(tasks) {
  const taskNames = Object.keys(tasks);
  const resolved = {};
  const visiting = new Set();
  const sorted = [];
  const errors = [];

  function visit(name) {
    if (resolved[name]) return;
    if (visiting.has(name)) {
      errors.push(new Error(`cycle detected involving ${name}`));
      return;
    }
    visiting.add(name);
    const task = tasks[name];
    if (!task) {
      errors.push(new Error(`unknown dependency ${name}`));
      return;
    }
    for (const dep of task.deps) {
      if (!tasks[dep]) {
        errors.push(new Error(`unknown dependency ${dep}`));
        continue;
      }
      visit(dep);
    }
    visiting.delete(name);
    sorted.push(name);
  }

  for (const name of taskNames) {
    visit(name);
  }

  if (errors.length > 0) {
    throw errors[0];
  }

  const batches = [];
  const inProgress = new Set();
  for (const name of sorted) {
    const task = tasks[name];
    const deps = task.deps;
    if (deps.length === 0 || deps.every(d => resolved[d] !== undefined)) {
      if (!batches.length || batches[batches.length - 1].length >= deps.length) {
        batches.push([]);
      }
      batches[batches.length - 1].push(name);
    } else {
      if (!batches.length || batches[batches.length - 1].length >= deps.length) {
        batches.push([]);
      }
      batches[batches.length - 1].push(name);
    }
  }

  for (const batch of batches) {
    const promises = batch.map(async (name) => {
      const task = tasks[name];
      const deps = task.deps;
      const depValues = {};
      for (const dep of deps) {
        depValues[dep] = resolved[dep];
      }
      try {
        const result = await task.run(depValues);
        resolved[name] = result;
      } catch (err) {
        throw err;
      }
    });
    await Promise.all(promises);
  }

  return resolved;
};
```

