I'll create a type‑safe event bus where each event key has a payload type defined in the generic record, and I'll enforce that `void` events are emitted without a second argument while all other events require one. The implementation will use a map of listeners, a generic `on` method that returns an unsubscribe function, and an `emit` method that checks the payload type at compile time and runtime.

ANSWER:
```typescript
export class Bus<E extends Record<string, unknown>> {
  private listeners = new Map<keyof E, Set<(payload: E[keyof E]) => void>>();

  on<K extends keyof E>(
    key: K,
    fn: (payload: E[K]) => void
  ): () => void {
    if (!this.listeners.has(key)) {
      this.listeners.set(key, new Set());
    }
    const set = this.listeners.get(key)!;
    set.add(fn);
    return () => {
      set.delete(fn);
      if (set.size === 0) {
        this.listeners.delete(key);
      }
    };
  }

  emit<K extends keyof E>(key: K, payload?: E[K]): void {
    const listeners = this.listeners.get(key);
    if (!listeners) return;

    // Runtime check for void events
    const payloadType = typeof payload;
    const expectedType = typeof undefined as unknown as string; // placeholder for void
    const isVoid = payloadType === 'undefined' && (payload as any) === undefined;

    // If the event expects void, payload must be undefined
    if (isVoid && payload !== undefined) {
      throw new Error(`Event "${String(key)}" expects no payload`);
    }

    // If the event expects a payload, it must be provided
    if (!isVoid && payload === undefined) {
      throw new Error(`Event "${String(key)}" requires a payload`);
    }

    for (const fn of listeners) {
      fn(payload as E[K]);
    }
  }
}
```

