  type RequiredKeys<T> = {
    [K in keyof T]-?: undefined extends T[K] ? never : K;
  }[keyof T];

  type OptionalKeys<T> = {
    [K in keyof T]-?: undefined extends T[K] ? K : never;
  }[keyof T];

  type BuilderState<T, S extends Set<keyof T>> = {
    set: <K extends keyof T>(
      key: K,
      value: K extends RequiredKeys<T> ? T[K] : K extends OptionalKeys<T> ? T[K] : never
    ) => Builder<T, S | Set<K>>;
    build: S extends RequiredKeys<T> ? never : () => { [K in keyof T]: K extends S ? T[K] : never };
  };

