  export function builder<T>(): Builder<T, Set<never>> {
    return {
      set(key, value) {
        return {
          set: (k, v) => builder(),
          build: () => ({ [key]: value } as any)
        } as any;
      },
      build() {
        throw new Error('build() called before all required keys are set');
      }
    } as any;
  }
