I will implement a generic `curry` function that uses TypeScript's conditional types and recursion to enforce correct argument splitting and typing. The solution will track the number of expected arguments and the return type, ensuring that each partial application reduces the arity correctly and that the final call returns the proper result type. Edge cases such as zero‑arity functions and functions with no arguments will be handled by returning the result type directly or by a function that takes no parameters.

ANSWER:
```typescript
export type Curry<F extends (...args: any[]) => any> = 
  F extends (...args: infer A) => infer R
    ? A extends []
      ? () => R
      : Curried<F, A, R>
    : never;

type Curried<F, A extends any[], R> = 
  A extends [infer First, ...infer Rest]
    ? (arg: First) => Curried<F, Rest, R>
    : (...args: A) => R;

export function curry<F extends (...args: any[]) => any>(fn: F): Curry<F> {
  return function curried(...args: any[]) {
    if (args.length >= fn.length) {
      return fn(...args);
    }
    return (...moreArgs: any[]) => curried(...args, ...moreArgs);
  } as Curry<F>;
}
```

