The key challenge is ensuring that after `isOk(r)` the value is typed as T with no undefined, and that accessing `.value` on an Err variant is a compile error. This requires careful use of TypeScript's type system with the `in` operator and conditional types to create the proper narrowing behavior.

```typescript
export type Result<T, E> = { ok: true; value: T } | { ok: false; value: E };

export function ok<T, E>(value: T): Result<T, E> {
  return { ok: true, value };
}

export function err<T, E>(error: E): Result<T, E> {
  return { ok: false, value: error };
}

export function isOk<T, E>(r: Result<T, E>): r is { ok: true; value: T } {
  return r.ok;
}

export function isErr<T, E>(r: Result<T, E>): r is { ok: false; value: E } {
  return !r.ok;
}

export function map<T, E, U>(r: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  if (r.ok) {
    return ok(fn(r.value));
  }
  return r;
}

export function unwrapOr<T, E>(r: Result<T, E>, defaultValue: T): T {
  if (r.ok) {
    return r.value;
  }
  return defaultValue;
}
