I will create a TypeScript module that defines a `defineRoutes` function with precise generic typing to ensure compile‑time safety for route interpolation. The implementation will use conditional types to differentiate between paths with and without parameters, and will enforce that the number of supplied arguments matches the number of `:name` placeholders, causing a compile error for mismatches.

ANSWER:
```typescript
// sol.ts
type PathParams<T extends string> = T extends `${infer _Start}:${infer Param}/${infer Rest}`
  ? Param | PathParams<`${_Start}:${Param}/${Rest}`>
  : T extends `${infer _Start}:${infer Param}`
  ? Param
  : never;

type RouteFn<T extends string> = T extends `${infer _Start}:${infer Param}/${infer Rest}`
  ? (params: { [K in PathParams<T>]: string }) => string
  : T extends `${infer _Start}:${infer Param}`
  ? (params: { [K in PathParams<T>]: string }) => string
  : () => string;

export function defineRoutes<T extends Record<string, string>>(routes: T): {
  [K in keyof T]: RouteFn<T[K]>;
} {
  const result: any = {};
  for (const key in routes) {
    const path = routes[key];
    const paramNames = path.match(/:(\w+)/g)?.map(p => p.slice(1)) || [];
    if (paramNames.length === 0) {
      result[key] = () => path;
    } else {
      result[key] = (params: { [K in PathParams<typeof path>]: string }) => {
        let interpolated = path;
        for (const name of paramNames) {
          if (!(name in params)) {
            throw new Error(`Missing param: ${name}`);
          }
          interpolated = interpolated.replace(`:${name}`, params[name]);
        }
        return interpolated;
      };
    }
  }
  return result;
}
```

