I will implement `DeepPartial` using recursive conditional types to make every property optional at any depth, while preserving the original type for arrays and functions. The `applyPatch` function will perform a shallow copy of the base object, recursively merge plain objects, replace arrays entirely when a patch array is provided, and ignore `undefined` values in the patch to keep the original property unchanged.

ANSWER:
```typescript
export type DeepPartial<T> = T extends (infer U)[]
  ? DeepPartial<U>[]
  : T extends Function
  ? T
  : { [K in keyof T]?: DeepPartial<T[K]> };

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) return base;
  if (Array.isArray(base) && Array.isArray(patch)) {
    return patch.map(item => applyPatch(item, item)) as unknown as T;
  }
  if (typeof base === 'object' && base !== null && typeof patch === 'object' && patch !== null) {
    const result = { ...base } as T;
    for (const key in patch) {
      if (patch[key] === undefined) continue;
      (result as any)[key] = applyPatch((base as any)[key], (patch as any)[key]);
    }
    return result;
  }
  return patch as unknown as T;
}
```

